import{_ as e,c as a,o,a2 as r}from"./chunks/framework.CHomSxuB.js";const u=JSON.parse('{"title":"3. 连板接力与情绪闸门：抛硬币与择时幻觉（Step 5 / V0.5）","description":"","frontmatter":{},"headers":[],"relativePath":"A股量化验证/3-连板接力与情绪闸门.md","filePath":"A股量化验证/3-连板接力与情绪闸门.md"}'),d={name:"A股量化验证/3-连板接力与情绪闸门.md"};function n(h,t,s,l,i,_){return o(),a("div",null,t[0]||(t[0]=[r('<h1 id="_3-连板接力与情绪闸门-抛硬币与择时幻觉-step-5-v0-5" tabindex="-1">3. 连板接力与情绪闸门：抛硬币与择时幻觉（Step 5 / V0.5） <a class="header-anchor" href="#_3-连板接力与情绪闸门-抛硬币与择时幻觉-step-5-v0-5" aria-label="Permalink to &quot;3. 连板接力与情绪闸门：抛硬币与择时幻觉（Step 5 / V0.5）&quot;">​</a></h1><blockquote><p>两连发证伪： ① 连板接力本身（2进3 / 3进4 无差别）≈ <strong>抛硬币</strong> —— <code>NO_EDGE</code> ② &quot;情绪温度计&quot;择时（退潮期提前规避）<strong>无单调性</strong> —— <code>GATE_NO_EDGE</code> 卷宗：<code>bench-step5-20260819</code>（基线+闸门）+ <code>v0.5_sentiment_gate_prereg.md</code></p></blockquote><h2 id="第一发-连板接力基线-step-5" tabindex="-1">第一发：连板接力基线（Step 5） <a class="header-anchor" href="#第一发-连板接力基线-step-5" aria-label="Permalink to &quot;第一发：连板接力基线（Step 5）&quot;">​</a></h2><h3 id="故事" tabindex="-1">故事 <a class="header-anchor" href="#故事" aria-label="Permalink to &quot;故事&quot;">​</a></h3><p>&quot;连板股有连板基因，2 进 3、3 进 4 自带正期望&quot;——打板圈最流行的信仰之一。</p><h3 id="实测-243-交易日-成分池-1-324-只" tabindex="-1">实测（243 交易日，成分池 1,324 只） <a class="header-anchor" href="#实测-243-交易日-成分池-1-324-只" aria-label="Permalink to &quot;实测（243 交易日，成分池 1,324 只）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>晋级</th><th>n</th><th>Ev(Close)</th><th>p</th><th>尾部</th></tr></thead><tbody><tr><td>2进3</td><td>2,120</td><td>+0.83%</td><td>0.5045</td><td>—</td></tr><tr><td>3进4</td><td>791</td><td>+0.85%</td><td>0.5033</td><td>p10 = <strong>−10.2%</strong></td></tr></tbody></table><p>期望值看似为正（+0.8%），但 bootstrap p≈0.50——<strong>与抛硬币无统计差异</strong>，即 &quot;+0.83% 是幸存者平均，真实分布是 iid 噪声&quot;，且 3进4 尾部 p10 = −10.2% 说明 <strong>下行尾部极险</strong>（核按钮）。</p><h3 id="裁决-no-edge" tabindex="-1">裁决：<code>NO_EDGE</code> <a class="header-anchor" href="#裁决-no-edge" aria-label="Permalink to &quot;裁决：`NO_EDGE`&quot;">​</a></h3><p>连板晋级不产生&quot;可辨识的正期望&quot;；看到的正均值来自分布右偏，不是可持续 edge。 <strong>负偏态 + 高方差 + iid</strong> —— 教科书式的&quot;赌徒幻觉&quot;结构。</p><h2 id="第二发-情绪闸门-v0-5-预注册证伪系列" tabindex="-1">第二发：情绪闸门（V0.5，预注册证伪系列） <a class="header-anchor" href="#第二发-情绪闸门-v0-5-预注册证伪系列" aria-label="Permalink to &quot;第二发：情绪闸门（V0.5，预注册证伪系列）&quot;">​</a></h2><h3 id="故事-1" tabindex="-1">故事 <a class="header-anchor" href="#故事-1" aria-label="Permalink to &quot;故事&quot;">​</a></h3><p>既然接力 Ev 是噪声，那是不是&quot;退潮期不做、亢奋期才做&quot;就能截住尾部？ V0.5 构造<strong>昨日连板溢价指数 S_T</strong>（昨日连板群体今天的赚钱效应）当 regime 闸门： S_T 冷 → 回避接力；S_T 热 → 参与接力。</p><h3 id="实测-242-天-s-t-覆盖-置换检验" tabindex="-1">实测（242 天 S_T 覆盖，置换检验） <a class="header-anchor" href="#实测-242-天-s-t-覆盖-置换检验" aria-label="Permalink to &quot;实测（242 天 S_T 覆盖，置换检验）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>假设</th><th>门槛</th><th>实测</th><th>结果</th></tr></thead><tbody><tr><td>H1 周期分离度</td><td>ΔEv &gt; +3.00% 且 p &lt; 0.01</td><td>ΔEv = <strong>+0.26%</strong>，置换 p = <strong>0.6975</strong></td><td>❌</td></tr><tr><td>H2 / H3（冷热区接力 vs 全体）</td><td>单调性</td><td><strong>无单调结构</strong></td><td>❌</td></tr></tbody></table><ul><li>十分位诊断：把 S_T 分十档看接力 Ev——<strong>没有任何档位能稳定分离</strong>；</li><li>连续相关性：r≈0.03（p=0.27）——昨日赚钱效应<strong>对次日接力毫无预测力</strong>；</li><li>阈值锚点有误不是主因（即使重选锚点，无单调性意味着不存在能切出区分度的点）。</li></ul><h3 id="裁决-gate-no-edge" tabindex="-1">裁决：<code>GATE_NO_EDGE</code> <a class="header-anchor" href="#裁决-gate-no-edge" aria-label="Permalink to &quot;裁决：`GATE_NO_EDGE`&quot;">​</a></h3><p><strong>连板溢价不存在日间序列相关性</strong>——&quot;情绪温度计&quot;是叙事，不是变量。 任何&quot;换成分位数锚点再试一次&quot;的想法都是 Data Snooping 入口，协议规定：<strong>记录并封存，不得调参重试</strong>。</p><h3 id="更深一层的推论-本轮最有价值的产出" tabindex="-1">更深一层的推论（本轮最有价值的产出） <a class="header-anchor" href="#更深一层的推论-本轮最有价值的产出" aria-label="Permalink to &quot;更深一层的推论（本轮最有价值的产出）&quot;">​</a></h3><blockquote><p>昨日连板群体的赚钱效应，对次日接力的收益分布没有预测力。 短线情绪在日频上<strong>不存在可被统计利用的惯性</strong>——这直接宣判了一大类 &quot;情绪周期择时&quot;策略的死刑，省下未来无数调参时间。</p></blockquote><hr><p><strong>验证线汇总导航</strong>：<a href="/A股量化验证/">返回 A股量化验证 首页</a> · <a href="/A股量化验证/2-公告排雷.html">上一线：公告排雷</a> · <a href="/A股量化验证/4-分歧低吸.html">下一线：分歧低吸</a></p>',22)]))}const p=e(d,[["render",n]]);export{u as __pageData,p as default};
